<section class="panel"><h1>تغییر آدرس صفحات</h1><p>برای آدرس قدیمی یک مقصد داخلی با انتقال دائمی ۳۰۱ ثبت کنید. نمونه: /product/old-name → /product/new-name</p><?php if($error): ?><p class="flash flash-error"><?= CHtml::encode($error) ?></p><?php endif; ?><?= CHtml::beginForm('','post') ?><div class="form-row"><div class="field"><label>مسیر قدیمی</label><?= CHtml::textField('source','',array('dir'=>'ltr','required'=>true)) ?></div><div class="field"><label>مسیر جدید</label><?= CHtml::textField('target','',array('dir'=>'ltr','required'=>true)) ?></div></div><?= CHtml::submitButton('ثبت تغییر آدرس',array('class'=>'btn btn-primary')) ?><?= CHtml::endForm() ?><?php foreach($rows as $row): ?><div class="summary-row"><span dir="ltr"><?= CHtml::encode($row['source'].' → '.$row['target']) ?></span><?= CHtml::beginForm(array('adminSeo/delete'),'post',array('data-confirm'=>'تغییر آدرس حذف شود؟')) ?><?= CHtml::hiddenField('source',$row['source'],array('id'=>false)) ?><?= CHtml::submitButton('حذف',array('class'=>'btn btn-outline')) ?><?= CHtml::endForm() ?></div><?php endforeach; ?></section>
